mapper.select:
select id, event_type, rule_name, point_value, daily_limit, status,
    create_by, create_time, update_by, update_time, remark from wl_point_rule

    del_flag = '0'
    and event_type = #{eventType}
    and status = #{status}

order by id asc

mapper.update:
update wl_point_rule set point_value = #{pointValue}, daily_limit = #{dailyLimit},
    status = #{status}, update_by = #{updateBy}, update_time = now(), remark = #{remark}
where id = #{id} and event_type = #{eventType} and del_flag = '0'

update wl_invitation set reward_status = 'REWARDED', inviter_point_record_id = #{pointRecordId},
    update_time = now() where invited_user_id = #{invitedUserId}
    and reward_status = 'PENDING' and del_flag = '0'

mapper.select:
select id, user_id, rule_id, event_type, biz_no, change_points,
    before_balance, after_balance, description, create_time
from wl_point_record

    del_flag = '0'
    and user_id = #{userId}
    and event_type = #{eventType}
    and biz_no = #{bizNo}

order by id desc
